import { ColumnMinInstance } from '../types/internal-table-types.js';
import type { TableVariantConfig } from '../types/shared-table-types.js';

// Apply given font style to all columns.  if it's 'text'
// set it to undefined at the column level
export function applyFontStyleToAllColumns(
  allColumns: ColumnMinInstance[],
  fontStyle: 'text' | 'code' | undefined,
) {
  allColumns.forEach(
    (column) =>
      (column.fontStyle = fontStyle === 'text' ? undefined : fontStyle),
  );
}

// Checks all columns, current variant and returns how the table level
// flag need to be set
export function applyFontStyleRulesFromColumnActions(
  allColumns: ColumnMinInstance[],
  variant: TableVariantConfig,
): 'text' | 'code' | undefined {
  const allColumnsAreCode = areAllColumnsFontStyleCode(allColumns);
  const allColumnsAreText = areAllColumnsFontStyleText(allColumns);

  if (allColumnsAreText || allColumnsAreCode) {
    applyFontStyleToAllColumns(allColumns, undefined);

    if (allColumnsAreCode && variant.fontStyle === 'text') {
      return 'code';
    }
    if (allColumnsAreText && variant.fontStyle === 'code') {
      return 'text';
    }
  }
  return undefined;
}

// checks if all of them are set to 'code'
export function areAllColumnsFontStyleCode(
  columns: ColumnMinInstance[],
): boolean {
  const allColumnsAreCode = columns.every(
    (column) => column.fontStyle === 'code',
  );
  return columns.length === 0 ? false : allColumnsAreCode;
}

// checks if all of them are set to 'text'
export function areAllColumnsFontStyleText(
  columns: ColumnMinInstance[],
): boolean {
  const allColumnsAreCode =
    columns.every((column) => column.fontStyle === 'text') || false;
  return columns.length === 0 ? false : allColumnsAreCode;
}
